package br.com.sussmartcare.triage.domain; import java.time.*; import java.util.*;
public class Triage {private UUID id;private UUID visitId;private TriageStatus status;private ClinicalPriority aiRecommendation;private Double aiConfidence;private String aiReasoning;private String aiModelName;private String aiModelVersion;private ClinicalPriority finalPriority;private UUID decidedBy;private Instant startedAt;private Instant decidedAt;private long version;private final List<TriageDomainEvent> changes=new ArrayList<>();private Triage(){}
 public static Triage start(UUID visitId){var t=new Triage();t.raise(new TriageDomainEvent.TriageStarted(UUID.randomUUID(),visitId,Instant.now()));return t;} public static Triage rehydrate(List<TriageDomainEvent> es){var t=new Triage();es.forEach(t::apply);return t;}
 public void assessment(ClinicalPriority p,double confidence,String reasoning,String model,String modelVersion){if(confidence<0||confidence>1)throw new IllegalArgumentException("Confiança deve estar entre 0 e 1");raise(new TriageDomainEvent.TriageAssessed(p,confidence,reasoning,model,modelVersion,Instant.now()));}
 public void confirm(ClinicalPriority p,UUID professional){if(professional==null)throw new IllegalArgumentException("Profissional é obrigatório");raise(new TriageDomainEvent.ClinicalPriorityConfirmed(p,professional,Instant.now()));}
 private void raise(TriageDomainEvent e){apply(e);changes.add(e);} private void apply(TriageDomainEvent e){if(e instanceof TriageDomainEvent.TriageStarted x){id=x.triageId();visitId=x.visitId();status=TriageStatus.STARTED;startedAt=x.occurredAt();}else if(e instanceof TriageDomainEvent.TriageAssessed x){aiRecommendation=x.recommendation();aiConfidence=x.confidence();aiReasoning=x.reasoning();aiModelName=x.modelName();aiModelVersion=x.modelVersion();status=TriageStatus.ASSESSED;}else if(e instanceof TriageDomainEvent.ClinicalPriorityConfirmed x){finalPriority=x.priority();decidedBy=x.professionalId();decidedAt=x.occurredAt();status=TriageStatus.CONFIRMED;}version++;}
 public List<TriageDomainEvent> pullChanges(){var c=List.copyOf(changes);changes.clear();return c;} public UUID getId(){return id;}public UUID getVisitId(){return visitId;}public TriageStatus getStatus(){return status;}public ClinicalPriority getAiRecommendation(){return aiRecommendation;}public Double getAiConfidence(){return aiConfidence;}public String getAiReasoning(){return aiReasoning;}public String getAiModelName(){return aiModelName;}public String getAiModelVersion(){return aiModelVersion;}public ClinicalPriority getFinalPriority(){return finalPriority;}public UUID getDecidedBy(){return decidedBy;}public Instant getStartedAt(){return startedAt;}public Instant getDecidedAt(){return decidedAt;}public long getVersion(){return version;}
}
